type Approval =
  | { status: 'pending'; initiatedBy: UserId }
  | { status: 'approved'; initiatedBy: UserId; approvedBy: UserId };

function approve(a: Approval, approver: UserId): Approval {
  if (a.status !== 'pending') throw new Conflict(a.status);
  if (a.initiatedBy === approver) throw new Forbidden('maker cannot approve');
  return { status: 'approved', initiatedBy: a.initiatedBy, approvedBy: approver };
}
